/*** MOS 6502 (NMOS) core from MAME, outside MAME's device framework ********

    The reference sound CPU for ApbArcade-QilinRecomp's tests. The opcode
    implementations are MAME's cpu/m6502/m6502.hxx, generated by MAME's
    m6502make.py from om6502.lst and dm6502.lst (all three vendored here,
    unmodified). This class keeps the member names that code uses; its
    declarations are copied from MAME's m6502.h, and m6502_reference.cpp
    carries MAME's m6502.cpp helpers (flags, decimal arithmetic, prefetch,
    interrupts, reset, the run loop). MAME revision: see ../README.md.

    MAME models every bus cycle, the opcode prefetch at the end of each
    instruction included, so a Bus sees exactly the accesses the chip makes.
    Beyond MAME's interface: step() (one instruction), set_state (to start
    from a native run's state) and elapsed() (within step(), the bus cycles
    so far: MAME's local time, which the board uses to time its chips).

*******************************************************************************/

#pragma once

#include <cstdint>

class m6502_device
{
public:
	// The bus: opcode fetches (read_sync), operand fetches (read_arg), data
	// reads (including the dummy reads the 6502 makes) and writes.
	struct Bus
	{
		virtual ~Bus() = default;
		virtual uint8_t read(uint16_t adr) = 0;
		virtual uint8_t read_sync(uint16_t adr) = 0;
		virtual uint8_t read_arg(uint16_t adr) = 0;
		virtual void write(uint16_t adr, uint8_t val) = 0;
	};

	enum { IRQ_LINE = 0, NMI_LINE = 1, V_LINE = 2 };

	explicit m6502_device(Bus &bus);

	void reset();                  // MAME's device_reset: the reset sequence runs on the next step
	int step();                    // runs one instruction (with its prefetch); returns its cycles
	int elapsed() const { return (1 << 20) - m_icount; }   // within step(): bus cycles counted so far
	void set_input_line(int line, bool asserted);

	uint16_t pc() const { return m_PC; }       // the address after the prefetched opcode
	uint16_t npc() const { return m_NPC; }     // the instruction about to run
	uint8_t a() const { return m_A; }
	uint8_t x() const { return m_X; }
	uint8_t y() const { return m_Y; }
	uint8_t p() const { return m_P; }
	uint8_t s() const { return static_cast<uint8_t>(m_SP); }
	uint8_t ir() const { return m_IR; }
	// The next step() runs the interrupt sequence (an IRQ or NMI was taken
	// at the last opcode fetch), or the reset sequence, not the opcode at npc().
	bool taking_interrupt() const { return m_irq_taken; }
	bool resetting() const { return m_inst_state == STATE_RESET; }
	// Sets the state as if the opcode at 'pc' had just been prefetched.
	void set_state(uint16_t pc, uint8_t a, uint8_t x, uint8_t y, uint8_t p, uint8_t s);

protected:
	enum {
		STATE_RESET = 0xff00
	};
	enum {
		F_N = 0x80,
		F_V = 0x40,
		F_E = 0x20, // 65ce02
		F_T = 0x20, // M740: replaces A with $00,X in some opcodes when set
		F_B = 0x10,
		F_D = 0x08,
		F_I = 0x04,
		F_Z = 0x02,
		F_C = 0x01
	};

	Bus &m_bus;

	uint16_t  m_PPC;             // previous program counter
	uint16_t  m_NPC;             // next start-of-instruction program counter
	uint16_t  m_PC;              // program counter
	uint16_t  m_SP;              // stack pointer (always 100 - 1FF)
	uint16_t  m_TMP;             // temporary internal values
	uint8_t   m_TMP2;            // another temporary internal value, 8 bits this time
	uint8_t   m_A;               // Accumulator
	uint8_t   m_X;               // X index register
	uint8_t   m_Y;               // Y index register
	uint8_t   m_P;               // Processor status
	uint8_t   m_IR;              // Prefetched instruction register
	int       m_inst_state_base; // Current instruction bank
	int m_inst_state, m_inst_substate;
	int m_icount;
	bool m_nmi_state, m_irq_state, m_apu_irq_state, m_v_state, m_rdy_state;
	bool m_nmi_pending, m_irq_taken, m_sync, m_inhibit_interrupts;
	bool m_irq_sampled, m_nmi_sampled;

	uint8_t read(uint16_t adr) { return m_bus.read(adr); }
	uint8_t read_9(uint16_t adr) { return m_bus.read(adr); }
	uint8_t read_sync(uint16_t adr) { return m_bus.read_sync(adr); }
	void write(uint16_t adr, uint8_t val) { m_bus.write(adr, val); }
	void write_9(uint16_t adr, uint8_t val) { m_bus.write(adr, val); }
	uint8_t read_arg(uint16_t adr) { return m_bus.read_arg(adr); }
	uint8_t read_pc() { return read_arg(m_PC); }
	uint8_t read_pc_noirq() { return read_arg(m_PC); }
	uint8_t read_arg_noirq(uint16_t adr) { return read_arg(adr); }

	void prefetch_start();
	void prefetch_end();
	void prefetch_end_noirq();
	void set_nz(uint8_t v);
	void sample_interrupt() { m_irq_sampled = m_irq_state || m_apu_irq_state; m_nmi_sampled = m_nmi_pending; }

	// MAME's cpu_device hooks the generated code calls.
	static bool access_to_be_redone() { return false; }
	static void debugger_wait_hook() {}
	static void standard_irq_callback(int, uint16_t) {}

	void do_exec_full();
	void do_exec_partial();

	static inline bool page_changing(uint16_t base, int delta) { return ((base + delta) ^ base) & 0xff00; }
	static inline uint16_t set_l(uint16_t base, uint8_t val) { return (base & 0xff00) | val; }
	static inline uint16_t set_h(uint16_t base, uint8_t val) { return (base & 0x00ff) | (val << 8); }

	inline void dec_SP() { m_SP = set_l(m_SP, m_SP-1); }
	inline void inc_SP() { m_SP = set_l(m_SP, m_SP+1); }

	void do_adc_d(uint8_t val);
	void do_adc_nd(uint8_t val);
	void do_sbc_d(uint8_t val);
	void do_sbc_nd(uint8_t val);
	void do_arr_d();
	void do_arr_nd();

	void do_adc(uint8_t val);
	void do_cmp(uint8_t val1, uint8_t val2);
	void do_sbc(uint8_t val);
	void do_bit(uint8_t val);
	void do_arr();
	uint8_t do_asl(uint8_t v);
	uint8_t do_lsr(uint8_t v);
	uint8_t do_ror(uint8_t v);
	uint8_t do_rol(uint8_t v);
	uint8_t do_asr(uint8_t v);

#define O(o) void o ## _full(); void o ## _partial()

	// NMOS 6502 opcodes
	// documented opcodes
	O(adc_aba); O(adc_abx); O(adc_aby); O(adc_idx); O(adc_idy); O(adc_imm); O(adc_zpg); O(adc_zpx);
	O(and_aba); O(and_abx); O(and_aby); O(and_imm); O(and_idx); O(and_idy); O(and_zpg); O(and_zpx);
	O(asl_aba); O(asl_abx); O(asl_acc); O(asl_zpg); O(asl_zpx);
	O(bcc_rel);
	O(bcs_rel);
	O(beq_rel);
	O(bit_aba); O(bit_zpg);
	O(bmi_rel);
	O(bne_rel);
	O(bpl_rel);
	O(brk_imp);
	O(bvc_rel);
	O(bvs_rel);
	O(clc_imp);
	O(cld_imp);
	O(cli_imp);
	O(clv_imp);
	O(cmp_aba); O(cmp_abx); O(cmp_aby); O(cmp_idx); O(cmp_idy); O(cmp_imm); O(cmp_zpg); O(cmp_zpx);
	O(cpx_aba); O(cpx_imm); O(cpx_zpg);
	O(cpy_aba); O(cpy_imm); O(cpy_zpg);
	O(dec_aba); O(dec_abx); O(dec_zpg); O(dec_zpx);
	O(dex_imp);
	O(dey_imp);
	O(eor_aba); O(eor_abx); O(eor_aby); O(eor_idx); O(eor_idy); O(eor_imm); O(eor_zpg); O(eor_zpx);
	O(inc_aba); O(inc_abx); O(inc_zpg); O(inc_zpx);
	O(inx_imp);
	O(iny_imp);
	O(jmp_adr); O(jmp_ind);
	O(jsr_adr);
	O(lda_aba); O(lda_abx); O(lda_aby); O(lda_idx); O(lda_idy); O(lda_imm); O(lda_zpg); O(lda_zpx);
	O(ldx_aba); O(ldx_aby); O(ldx_imm); O(ldx_zpg); O(ldx_zpy);
	O(ldy_aba); O(ldy_abx); O(ldy_imm); O(ldy_zpg); O(ldy_zpx);
	O(lsr_aba); O(lsr_abx); O(lsr_acc); O(lsr_zpg); O(lsr_zpx);
	O(nop_imp);
	O(ora_aba); O(ora_abx); O(ora_aby); O(ora_imm); O(ora_idx); O(ora_idy); O(ora_zpg); O(ora_zpx);
	O(pha_imp);
	O(php_imp);
	O(pla_imp);
	O(plp_imp);
	O(rol_aba); O(rol_abx); O(rol_acc); O(rol_zpg); O(rol_zpx);
	O(ror_aba); O(ror_abx); O(ror_acc); O(ror_zpg); O(ror_zpx);
	O(rti_imp);
	O(rts_imp);
	O(sbc_aba); O(sbc_abx); O(sbc_aby); O(sbc_idx); O(sbc_idy); O(sbc_imm); O(sbc_zpg); O(sbc_zpx);
	O(sec_imp);
	O(sed_imp);
	O(sei_imp);
	O(sta_aba); O(sta_abx); O(sta_aby); O(sta_idx); O(sta_idy); O(sta_zpg); O(sta_zpx);
	O(stx_aba); O(stx_zpg); O(stx_zpy);
	O(sty_aba); O(sty_zpg); O(sty_zpx);
	O(tax_imp);
	O(tay_imp);
	O(tsx_imp);
	O(txa_imp);
	O(txs_imp);
	O(tya_imp);

	// exceptions
	O(reset);

	// undocumented reliable instructions
	O(dcp_aba); O(dcp_abx); O(dcp_aby); O(dcp_idx); O(dcp_idy); O(dcp_zpg); O(dcp_zpx);
	O(isb_aba); O(isb_abx); O(isb_aby); O(isb_idx); O(isb_idy); O(isb_zpg); O(isb_zpx);
	O(lax_aba); O(lax_aby); O(lax_idx); O(lax_idy); O(lax_zpg); O(lax_zpy);
	O(rla_aba); O(rla_abx); O(rla_aby); O(rla_idx); O(rla_idy); O(rla_zpg); O(rla_zpx);
	O(rra_aba); O(rra_abx); O(rra_aby); O(rra_idx); O(rra_idy); O(rra_zpg); O(rra_zpx);
	O(sax_aba); O(sax_idx); O(sax_zpg); O(sax_zpy);
	O(sbx_imm);
	O(sha_aby); O(sha_idy);
	O(shs_aby);
	O(shx_aby);
	O(shy_abx);
	O(slo_aba); O(slo_abx); O(slo_aby); O(slo_idx); O(slo_idy); O(slo_zpg); O(slo_zpx);
	O(sre_aba); O(sre_abx); O(sre_aby); O(sre_idx); O(sre_idy); O(sre_zpg); O(sre_zpx);

	// undocumented unreliable instructions
	//   behaviour differs between visual6502 and online docs, which
	//   is a clear sign reliability is not to be expected
	//   implemented version follows visual6502
	O(anc_imm);
	O(ane_imm);
	O(arr_imm);
	O(asr_imm);
	O(las_aby);
	O(lxa_imm);

	// nop variants
	O(nop_imm); O(nop_aba); O(nop_abx); O(nop_zpg); O(nop_zpx);

	// system killers
	O(kil_non);

#undef O
};
